"""Half-open integer interval utilities.

An interval is a pair ``(start, end)`` meaning the half-open range ``[start, end)``.
Pairs with ``start >= end`` are empty and ignored everywhere. All functions accept
lists or tuples of pairs in any order and return lists of ``(start, end)`` tuples
sorted by start.
"""


def _valid_sorted(intervals):
    """Filter out empty intervals and sort the rest by start."""
    return sorted((int(s), int(e)) for s, e in intervals if int(s) < int(e))


def merge(intervals):
    """Merge overlapping and touching intervals into a minimal sorted list."""
    ivs = _valid_sorted(intervals)
    merged = []
    for s, e in ivs:
        if merged and s <= merged[-1][1]:  # overlapping or touching
            if e > merged[-1][1]:
                merged[-1] = (merged[-1][0], e)
        else:
            merged.append((s, e))
    return merged


def free_gaps(intervals, window):
    """Return maximal sub-ranges of ``window`` covered by no interval, in order."""
    ws, we = window
    if ws >= we:
        return []
    merged = merge(intervals)
    gaps = []
    cursor = ws
    for s, e in merged:
        if e <= cursor:
            continue  # ends before the uncovered region
        if s > cursor:
            gaps.append((cursor, min(s, we)))
            cursor = min(s, we)
        if e >= we:
            break
        cursor = max(cursor, e)
        if cursor >= we:
            break
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals):
    """Largest number of non-empty intervals covering a single common point."""
    ivs = _valid_sorted(intervals)
    if not ivs:
        return 0
    events = []
    for s, e in ivs:
        events.append((s, 1))   # start: +1
        events.append((e, -1))  # end: -1, processed first at equal points
    events.sort(key=lambda ev: (ev[0], ev[1]))
    depth = 0
    best = 0
    for _, delta in events:
        depth += delta
        if depth > best:
            best = depth
    return best

